INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('3_4_Sit-Up', '3/4 Sit-Up', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie down on the floor and secure your feet. Your legs should be bent at the knees. Place your hands behind or to the side of your head. You will begin with your back on the ground. This will be your starting position. Flex your hips and spine to raise your torso toward your knees. At the top of the contraction your torso should be perpendicular to the ground. Reverse the motion, going only ¾ of the way down. Repeat for the recommended amount of repetitions.'),
('90_90_Hamstring', '90/90 Hamstring', 'legs', ARRAY['legs']::text[], 'bodyweight', 'stretching', 'beginner', 'Lie on your back, with one leg extended straight out. With the other leg, bend the hip and knee to 90 degrees. You may brace your leg with your hands if necessary. This will be your starting position. Extend your leg straight into the air, pausing briefly at the top. Return the leg to the starting position. Repeat for 10-20 repetitions, and then switch to the other leg.'),
('Ab_Crunch_Machine', 'Ab Crunch Machine', 'core', ARRAY[]::text[], 'machine', 'strength', 'intermediate', 'Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position. At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs '),
('Ab_Roller', 'Ab Roller', 'core', ARRAY['shoulders']::text[], 'other', 'strength', 'intermediate', 'Hold the Ab Roller with both hands and kneel on the floor. Now place the ab roller on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position. Slowly roll the ab roller straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement. After a pause at the stretched position, start pulling yo'),
('Adductor', 'Adductor', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Lie face down with one leg on a foam roll. Rotate the leg so that the foam roll contacts against your inner thigh. Shift as much weight onto the foam roll as can be tolerated. While trying to relax the muscles if the inner thigh, roll over the foam between your hip and knee, holding points of tension for 10-30 seconds. Repeat with the other leg.'),
('Adductor_Groin', 'Adductor/Groin', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Lie on your back with your feet raised towards the ceiling. Have your partner hold your feet or ankles. Abduct your legs as far as you can. This will be your starting position. Attempt to squeeze your legs together for 10 or more seconds, while your partner prevents you from doing so. Now, relax the muscles in your legs as your partner pushes your feet apart, stretching as far as is comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or in'),
('Advanced_Kettlebell_Windmill', 'Advanced Kettlebell Windmill', 'core', ARRAY['legs','legs','shoulders']::text[], 'kettlebell', 'strength', 'intermediate', 'Clean and press a kettlebell overhead with one arm. Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Keep the non-working arm behind your back and turn your feet out at a forty-five degree angle from the arm with the kettlebell. Lower yourself as far as possible. Pause for a second and reverse the motion back to the starting position.'),
('Air_Bike', 'Air Bike', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position. Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position. Now simultaneously, slowly go through a cycle pedal motion kicking forward with the right leg and bringing '),
('All_Fours_Quad_Stretch', 'All Fours Quad Stretch', 'legs', ARRAY['legs']::text[], 'bodyweight', 'stretching', 'intermediate', 'Start off on your hands and knees, then lift your leg off the floor and hold the foot with your hand. Use your hand to hold the foot or ankle, keeping the knee fully flexed, stretching the quadriceps and hip flexors. Focus on extending your hips, thrusting them towards the floor. Hold for 10-20 seconds and then switch sides.'),
('Alternate_Hammer_Curl', 'Alternate Hammer Curl', 'arms', ARRAY['arms']::text[], 'dumbbell', 'strength', 'beginner', 'Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso. The palms of the hands should be facing your torso. This will be your starting position. While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the b'),
('Alternate_Heel_Touchers', 'Alternate Heel Touchers', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart. Your arms should be extended by your side. This will be your starting position. Crunch over your torso forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement. Now go back slowly to the starting position as you inhale. Now crunch over your torso forward and up around 3-4 inches to the left side and touch your'),
('Alternate_Incline_Dumbbell_Curl', 'Alternate Incline Dumbbell Curl', 'arms', ARRAY['arms']::text[], 'dumbbell', 'strength', 'beginner', 'Sit down on an incline bench with a dumbbell in each hand being held at arms length. Tip: Keep the elbows close to the torso.This will be your starting position. While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. As you do so, rotate the hand so that the palm is facing up. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze '),
('Alternate_Leg_Diagonal_Bound', 'Alternate Leg Diagonal Bound', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Assume a comfortable stance with one foot slightly in front of the other. Begin by pushing off with the front leg, driving the opposite knee forward and as high as possible before landing. Attempt to cover as much distance to each side with each bound. It may help to use a line on the ground to guage distance from side to side. Repeat the sequence with the other leg.'),
('Alternating_Cable_Shoulder_Press', 'Alternating Cable Shoulder Press', 'shoulders', ARRAY['arms']::text[], 'cable', 'strength', 'beginner', 'Move the cables to the bottom of the tower and select an appropriate weight. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position. Keeping your head and chest up, extend through the elbow to press one side directly over head. After pausing at the top, return to the starting position and repeat on the opposite side.'),
('Alternating_Deltoid_Raise', 'Alternating Deltoid Raise', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'In a standing position, hold a pair of dumbbells at your side. Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating. Return the weights to your side. On the next repetition, raise the weights laterally, raising them out to your side to about shoulder height. Return the weights to the starting position and continue alternating to the front and side.'),
('Alternating_Floor_Press', 'Alternating Floor Press', 'chest', ARRAY['core','shoulders','arms']::text[], 'kettlebell', 'strength', 'beginner', 'Lie on the floor with two kettlebells next to your shoulders. Position one in place on your chest and then the other, gripping the kettlebells on the handle with the palms facing forward. Extend both arms, so that the kettlebells are being held above your chest. Lower one kettlebell, bringing it to your chest and turn the wrist in the direction of the locked out kettlebell. Raise the kettlebell and repeat on the opposite side.'),
('Alternating_Hang_Clean', 'Alternating Hang Clean', 'legs', ARRAY['arms','legs','arms','legs','back','back']::text[], 'kettlebell', 'strength', 'intermediate', 'Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead. Clean one kettlebell to your shoulder and hold on to the other kettlebell in a hanging position. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so. Lower the cleaned kettlebell to a hanging position and clean the alternate kettlebell. Repeat.'),
('Alternating_Kettlebell_Press', 'Alternating Kettlebell Press', 'shoulders', ARRAY['arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so. Press one directly overhead by extending through the elbow, turning it so the palm faces forward while holding the other kettlebell stationary . Lower the pressed kettlebell to the starting position and immediately press with your other arm.'),
('Alternating_Kettlebell_Row', 'Alternating Kettlebell Row', 'back', ARRAY['arms','back']::text[], 'kettlebell', 'strength', 'intermediate', 'Place two kettlebells in front of your feet. Bend your knees slightly and push your butt out as much as possible. As you bend over to get into the starting position grab both kettlebells by the handles. Pull one kettlebell off of the floor while holding on to the other kettlebell. Retract the shoulder blade of the working side, as you flex the elbow, drawing the kettlebell towards your stomach or rib cage. Lower the kettlebell in the working arm and repeat with your other arm.'),
('Alternating_Renegade_Row', 'Alternating Renegade Row', 'back', ARRAY['core','arms','chest','back','arms']::text[], 'kettlebell', 'strength', 'expert', 'Place two kettlebells on the floor about shoulder width apart. Position yourself on your toes and your hands as though you were doing a pushup, with the body straight and extended. Use the handles of the kettlebells to support your upper body. You may need to position your feet wide for support. Push one kettlebell into the floor and row the other kettlebell, retracting the shoulder blade of the working side as you flex the elbow, pulling it to your side. Then lower the kettlebell to the floor a'),
('Ankle_Circles', 'Ankle Circles', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Use a sturdy object like a squat rack to hold yourself. Lift the right leg in the air (just around 2 inches from the floor) and perform a circular motion with the big toe. Pretend that you are drawing a big circle with it. Tip: One circle equals 1 repetition. Breathe normally as you perform the movement. When you are done with the right foot, then repeat with the left leg.'),
('Ankle_On_The_Knee', 'Ankle On The Knee', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'From a lying position, bend your knees and keep your feet on the floor. Place your ankle of one foot on your opposite knee. Grasp the thigh or knee of the bottom leg and pull both of your legs into the chest. Relax your neck and shoulders. Hold for 10-20 seconds and then switch sides.'),
('Anterior_Tibialis-SMR', 'Anterior Tibialis-SMR', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Begin seated on the ground with your legs bent and your feet on the floor. Using a Muscle Roller or a rolling pin, apply pressure to the muscles on the outside of your shins. Work from just below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat on the other leg.'),
('Anti-Gravity_Press', 'Anti-Gravity Press', 'shoulders', ARRAY['back','back','arms']::text[], 'barbell', 'strength', 'beginner', 'Place a bar on the ground behind the head of an incline bench. Lay on the bench face down. With a pronated grip, pick the barbell up from the floor. Flex the elbows, performing a reverse curl to bring the bar near your chest. This will be your starting position. To begin, press the barbell out in front of your head by extending your elbows. Keep your arms parallel to the ground throughout the movement. Return to the starting position and repeat to complete the set.'),
('Arm_Circles', 'Arm Circles', 'shoulders', ARRAY['back']::text[], 'other', 'stretching', 'beginner', 'Stand up and extend your arms straight out by the sides. The arms should be parallel to the floor and perpendicular (90-degree angle) to your torso. This will be your starting position. Slowly start to make circles of about 1 foot in diameter with each outstretched arm. Breathe normally as you perform the movement. Continue the circular motion of the outstretched arms for about ten seconds. Then reverse the movement, going the opposite direction.'),
('Arnold_Dumbbell_Press', 'Arnold Dumbbell Press', 'shoulders', ARRAY['arms']::text[], 'dumbbell', 'strength', 'intermediate', 'Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl. Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward. Continue lifting the dumbbells until your arms are extended above you in straight arm posit'),
('Around_The_Worlds', 'Around The Worlds', 'chest', ARRAY['shoulders']::text[], 'dumbbell', 'strength', 'intermediate', 'Lay down on a flat bench holding a dumbbell in each hand with the palms of the hands facing towards the ceiling. Tip: Your arms should be parallel to the floor and next to your thighs. To avoid injury, make sure that you keep your elbows slightly bent. This will be your starting position. Now move the dumbbells by creating a semi-circle as you displace them from the initial position to over the head. All of the movement should happen with the arms parallel to the floor at all times. Breathe in a'),
('Atlas_Stone_Trainer', 'Atlas Stone Trainer', 'back', ARRAY['arms','arms','legs','legs','legs']::text[], 'other', 'strongman', 'intermediate', 'This trainer is effective for developing Atlas Stone strength for those who don''t have access to stones, and are typically made from bar ends or heavy pipe. Begin by loading the desired weight onto the bar. Straddle the weight, wrapping your arms around the implement, bending at the hips. Begin by pulling the weight up past the knees, extending through the hips. As the weight clears the knees, it can be lapped by resting it on your thighs and sitting back, hugging it tightly to your chest. Fini'),
('Atlas_Stones', 'Atlas Stones', 'back', ARRAY['core','legs','arms','legs','arms','legs','legs','back','legs','back']::text[], 'other', 'strongman', 'expert', 'Begin with the atlas stone between your feet. Bend at the hips to wrap your arms vertically around the Atlas Stone, attempting to get your fingers underneath the stone. Many stones will have a small flat portion on the bottom, which will make the stone easier to hold. Pulling the stone into your torso, drive through the back half of your feet to pull the stone from the ground. As the stone passes the knees, lap it by sitting backward, pulling the stone on top of your thighs. Sit low, getting the'),
('Axle_Deadlift', 'Axle Deadlift', 'back', ARRAY['arms','legs','legs','back','legs','back']::text[], 'other', 'strongman', 'intermediate', 'Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an over/under grip. With your feet and your grip set, take a big breath and then lower your hips and flex the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. '),
('Back_Flyes_-_With_Bands', 'Back Flyes - With Bands', 'shoulders', ARRAY['back','arms']::text[], 'bands', 'strength', 'beginner', 'Run a band around a stationary post like that of a squat rack. Grab the band by the handles and stand back so that the tension in the band rises. Extend and lift the arms straight in front of you. Tip: Your arms should be straight and parallel to the floor while perpendicular to your torso. Your feet should be firmly planted on the floor spread at shoulder width. This will be your starting position. As you exhale, move your arms to the sides and back. Keep your arms extended and parallel to the '),
('Backward_Drag', 'Backward Drag', 'legs', ARRAY['legs','arms','legs','legs','back']::text[], 'other', 'strongman', 'beginner', 'Load a sled with the desired weight, attaching a rope or straps to the sled that you can hold onto. Begin the exercise by moving backwards for a given distance. Leaning back, extend through the legs for short steps to move as quickly as possible.'),
('Backward_Medicine_Ball_Throw', 'Backward Medicine Ball Throw', 'shoulders', ARRAY[]::text[], 'other', 'plyometrics', 'beginner', 'This exercise is best done with a partner. If you lack a partner, the ball can be thrown and retrieved or thrown against a wall. Begin standing a few meters in front of your partner, both facing the same direction. Begin holding the ball between your legs. Squat down and then forcefully reverse direction, coming to full extension and you toss the ball over your head to your partner. Your partner can then roll the ball back to you. Repeat for the desired number of repetitions.'),
('Balance_Board', 'Balance Board', 'legs', ARRAY['legs','legs']::text[], 'other', 'strength', 'beginner', 'Place a balance board in front of you. Stand up on it and try to balance yourself. Hold the balance for as long as desired.'),
('Ball_Leg_Curl', 'Ball Leg Curl', 'legs', ARRAY['legs','legs']::text[], 'other', 'strength', 'beginner', 'Begin on the floor laying on your back with your feet on top of the ball. Position the ball so that when your legs are extended your ankles are on top of the ball. This will be your starting position. Raise your hips off of the ground, keeping your weight on the shoulder blades and your feet. Flex the knees, pulling the ball as close to you as you can, contracting the hamstrings. After a brief pause, return to the starting position.'),
('Band_Assisted_Pull-Up', 'Band Assisted Pull-Up', 'back', ARRAY['core','arms','back']::text[], 'other', 'strength', 'beginner', 'Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance. Pull the end of the band down, and place one bent knee into the loop, ensuring it won''t slip out. Take a medium to wide grip on the bar. This will be your starting position. Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movement'),
('Band_Good_Morning', 'Band Good Morning', 'legs', ARRAY['legs','back']::text[], 'bands', 'powerlifting', 'beginner', 'Using a 41 inch band, stand on one end, spreading your feet a small amount. Bend at the hips to loop the end of the band behind your neck. This will be your starting position. Keeping your legs straight, extend through the hips to come to a near vertical position. Ensure that you do not round your back as you go down back to the starting position.'),
('Band_Good_Morning_Pull_Through', 'Band Good Morning (Pull Through)', 'legs', ARRAY['legs','back']::text[], 'bands', 'powerlifting', 'beginner', 'Loop the band around a post. Standing a little ways away, loop the opposite end around the neck. Your hands can help hold the band in position. Begin by bending at the hips, getting your butt back as far as possible. Keep your back flat and bend forward to about 90 degrees. Your knees should be only slightly bent. Return to the starting position be driving through with the hips to come back to a standing position.'),
('Band_Hip_Adductions', 'Band Hip Adductions', 'legs', ARRAY[]::text[], 'bands', 'strength', 'beginner', 'Anchor a band around a solid post or other object. Stand with your left side to the post, and put your right foot through the band, getting it around the ankle. Stand up straight and hold onto the post if needed. This will be your starting position. Keeping the knee straight, raise your right legs out to the side as far as you can. Return to the starting position and repeat for the desired rep count. Switch sides.'),
('Band_Pull_Apart', 'Band Pull Apart', 'shoulders', ARRAY['back','back']::text[], 'bands', 'strength', 'beginner', 'Begin with your arms extended straight out in front of you, holding the band with both hands. Initiate the movement by performing a reverse fly motion, moving your hands out laterally to your sides. Keep your elbows extended as you perform the movement, bringing the band to your chest. Ensure that you keep your shoulders back during the exercise. Pause as you complete the movement, returning to the starting position under control.'),
('Band_Skull_Crusher', 'Band Skull Crusher', 'arms', ARRAY[]::text[], 'bands', 'strength', 'beginner', 'Secure a band to the base of a rack or the bench. Lay on the bench so that the band is lined up with your head. Take hold of the band, raising your elbows so that the upper arm is perpendicular to the floor. With the elbow flexed, the band should be above your head. This will be your starting position. Extend through the elbow to straighten your arm, keeping your upper arm in place. Pause at the top of the motion, and return to the starting position.'),
('Barbell_Ab_Rollout', 'Barbell Ab Rollout', 'core', ARRAY['back','shoulders']::text[], 'barbell', 'strength', 'intermediate', 'For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position. While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up, you should be keeping the abs tight and should maintain your back posture at all tim'),
('Barbell_Ab_Rollout_-_On_Knees', 'Barbell Ab Rollout - On Knees', 'core', ARRAY['back','shoulders']::text[], 'barbell', 'strength', 'expert', 'Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor. Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position. Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement. After a second pause at the stretched p'),
('Barbell_Bench_Press_-_Medium_Grip', 'Barbell Bench Press - Medium Grip', 'chest', ARRAY['shoulders','arms']::text[], 'barbell', 'strength', 'beginner', 'Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position. From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest. After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar us'),
('Barbell_Curl', 'Barbell Curl', 'arms', ARRAY['arms']::text[], 'barbell', 'strength', 'beginner', 'Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position. While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second'),
('Barbell_Curls_Lying_Against_An_Incline', 'Barbell Curls Lying Against An Incline', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Lie against an incline bench, with your arms holding a barbell and hanging down in a horizontal line. This will be your starting position. While keeping the upper arms stationary, curl the weight up as high as you can while squeezing the biceps. Breathe out as you perform this portion of the movement. Tip: Only the forearms should move. Do not swing the arms. After a second contraction, slowly go back to the starting position as you inhale. Tip: Make sure that you go all of the way down. Repeat '),
('Barbell_Deadlift', 'Barbell Deadlift', 'back', ARRAY['legs','arms','legs','legs','back','back','legs','back']::text[], 'barbell', 'strength', 'intermediate', 'Stand in front of a loaded barbell. While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps. While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright pos'),
('Barbell_Full_Squat', 'Barbell Full Squat', 'legs', ARRAY['legs','legs','legs','back']::text[], 'barbell', 'strength', 'intermediate', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoul'),
('Barbell_Glute_Bridge', 'Barbell Glute Bridge', 'legs', ARRAY['legs','legs']::text[], 'barbell', 'powerlifting', 'intermediate', 'Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor. Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet. Extend as far as possible, then reverse the motion to return to th'),
('Barbell_Guillotine_Bench_Press', 'Barbell Guillotine Bench Press', 'chest', ARRAY['shoulders','arms']::text[], 'barbell', 'strength', 'intermediate', 'Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position. As you breathe in, bring the bar down slowly until it is about 1 inch from your neck. After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze')
